export const cpuHdl: string = "// Nand to Tetris - Project 5\n// File name: capstone/HDL/CPU.hdl\n// Course: ETCCNT301 - Nand to Tetris - I\n// Student Roll Number: 2501730041 (K = 41)\n\n/**\n * The Hack Central Processing Unit (CPU).\n * Consists of an ALU, two registers (A and D), and a Program Counter (PC).\n * Executes instructions according to the Hack machine language specification:\n * - A-instruction: 0vvv vvvv vvvv vvvv (loads 15-bit constant into A register)\n * - C-instruction: 111a cccc ccdd djjj (computes ALU operation, stores in dest, jumps)\n */\n\nCHIP CPU {\n\n    IN  inM[16],         // M value input  (M = contents of RAM[A])\n        instruction[16], // Instruction for execution\n        reset;           // Signals whether to re-start the current\n                         // program (reset==1) or continue executing\n                         // the current program (reset==0).\n\n    OUT outM[16],        // M value output\n        writeM,          // Write to M?\n        addressM[15],    // Address in data memory (of M)\n        pc[15];          // Address of next instruction\n\n    PARTS:\n    // =========================================================================\n    // 1. INSTRUCTION DECODING\n    // =========================================================================\n    // instruction[15]: 0 -> A-instruction, 1 -> C-instruction\n    Not(in=instruction[15], out=isAInstruction);\n    Not(in=isAInstruction, out=isCInstruction);\n\n    // =========================================================================\n    // 2. A-REGISTER & A-INPUT MULTIPLEXER\n    // =========================================================================\n    // If A-instruction, load instruction constant into A.\n    // If C-instruction and dest bit d1 (instruction[5]) is set, load ALU output.\n    Mux16(a=instruction, b=aluOut, sel=instruction[15], out=inA);\n\n    // Load A register if it's an A-instruction OR (C-instruction AND d1==1)\n    Or(a=isAInstruction, b=instruction[5], out=loadA);\n    ARegister(in=inA, load=loadA, out=outA, out[0..14]=addressM);\n\n    // =========================================================================\n    // 3. ALU INPUT SELECTION (A vs M)\n    // =========================================================================\n    // If C-instruction and 'a' bit (instruction[12]) is 1, ALU y-input is inM; else outA.\n    Mux16(a=outA, b=inM, sel=instruction[12], out=outAM);\n\n    // =========================================================================\n    // 4. D-REGISTER\n    // =========================================================================\n    // D register is loaded only on C-instruction when dest bit d2 (instruction[4]) is set.\n    And(a=isCInstruction, b=instruction[4], out=loadD);\n    DRegister(in=aluOut, load=loadD, out=outD);\n\n    // =========================================================================\n    // 5. ALU OPERATION\n    // =========================================================================\n    // ALU inputs: x = D-register, y = A-register or Memory input\n    // Control bits: instruction[11..6] = zx, nx, zy, ny, f, no\n    ALU(x=outD, y=outAM,\n        zx=instruction[11],\n        nx=instruction[10],\n        zy=instruction[9],\n        ny=instruction[8],\n        f=instruction[7],\n        no=instruction[6],\n        out=aluOut,\n        out=outM,\n        zr=zrFlag,\n        ng=ngFlag);\n\n    // =========================================================================\n    // 6. MEMORY WRITE CONTROL (writeM)\n    // =========================================================================\n    // Write to memory M only on C-instruction when dest bit d3 (instruction[3]) is set.\n    And(a=isCInstruction, b=instruction[3], out=writeM);\n\n    // =========================================================================\n    // 7. JUMP LOGIC EVALUATION\n    // =========================================================================\n    // instruction[2] = j1 (out < 0)\n    // instruction[1] = j2 (out == 0)\n    // instruction[0] = j3 (out > 0)\n    \n    // Evaluate output signs from zr and ng flags\n    Not(in=zrFlag, out=notZr);\n    Not(in=ngFlag, out=notNg);\n    And(a=notZr, b=notNg, out=posFlag); // out > 0 if not zero and not negative\n\n    // Check individual conditions\n    And(a=instruction[2], b=ngFlag, out=passJLT);  // j1: negative\n    And(a=instruction[1], b=zrFlag, out=passJEQ);  // j2: zero\n    And(a=instruction[0], b=posFlag, out=passJGT); // j3: positive\n\n    // Combine conditions\n    Or(a=passJLT, b=passJEQ, out=passLE);\n    Or(a=passLE, b=passJGT, out=jumpConditionMet);\n\n    // Only jump if it's a C-instruction\n    And(a=isCInstruction, b=jumpConditionMet, out=loadPC);\n\n    // Program counter increments if load is 0\n    Not(in=loadPC, out=incPC);\n\n    // =========================================================================\n    // 8. PROGRAM COUNTER (PC)\n    // =========================================================================\n    PC(in=outA, load=loadPC, inc=incPC, reset=reset, out[0..14]=pc);\n}\n";

export const memHdl: string = "// Nand to Tetris - Project 5\n// File name: capstone/HDL/Memory.hdl\n// Course: ETCCNT301 - Nand to Tetris - I\n// Student Roll Number: 2501730041 (K = 41)\n\n/**\n * The complete address space of the Hack computer's memory,\n * including RAM and memory-mapped I/O devices (Screen and Keyboard).\n *\n * Address Space Mapping:\n * - 0x0000 to 0x3FFF (0 to 16383): RAM16K (Data RAM)\n * - 0x4000 to 0x5FFF (16384 to 24575): Screen memory map (8K words)\n * - 0x6000 (24576): Keyboard memory map (1 word, read-only)\n *\n * Address Decoding:\n * - address[14] == 0       --> RAM16K\n * - address[14..13] == 10  --> Screen\n * - address[14..13] == 11  --> Keyboard\n */\n\nCHIP Memory {\n    IN in[16], load, address[15];\n    OUT out[16];\n\n    PARTS:\n    // =========================================================================\n    // 1. WRITE LOAD DECODING\n    // =========================================================================\n    // address[14] selects between RAM (0) and I/O devices (1)\n    DMux(in=load, sel=address[14], a=loadRAM, b=loadIO);\n\n    // If I/O selected, address[13] selects between Screen (0) and Keyboard (1)\n    // Note: Keyboard register is read-only; write attempts to KBD are ignored.\n    DMux(in=loadIO, sel=address[13], a=loadScreen, b=dummyKbd);\n\n    // =========================================================================\n    // 2. MEMORY CHIPS INTEGRATION\n    // =========================================================================\n    // RAM16K: 16K words addressed by 14 address bits address[0..13]\n    RAM16K(in=in, load=loadRAM, address=address[0..13], out=ramOut);\n\n    // Screen: 8K words addressed by 13 address bits address[0..12]\n    Screen(in=in, load=loadScreen, address=address[0..12], out=screenOut);\n\n    // Keyboard: returns the ASCII code of currently pressed key (or 0)\n    Keyboard(out=kbdOut);\n\n    // =========================================================================\n    // 3. READ OUTPUT MULTIPLEXING\n    // =========================================================================\n    // address[13..14] determines the output source:\n    // sel = 00 -> ramOut (RAM lower 8K)\n    // sel = 01 -> ramOut (RAM upper 8K)\n    // sel = 10 -> screenOut (Screen)\n    // sel = 11 -> kbdOut (Keyboard)\n    Mux4Way16(a=ramOut, b=ramOut, c=screenOut, d=kbdOut, sel=address[13..14], out=out);\n}\n";

export const compHdl: string = "// Nand to Tetris - Project 5\n// File name: capstone/HDL/Computer.hdl\n// Course: ETCCNT301 - Nand to Tetris - I\n// Student Roll Number: 2501730041 (K = 41)\n\n/**\n * The Hack Computer platform, consisting of CPU, ROM32K, and Memory chips.\n * When reset is 0, the program stored in ROM executes sequentially or with jumps.\n * When reset is 1, the program restarts execution from ROM address 0.\n * Memory encompasses RAM16K, Screen memory-map (8K), and Keyboard register.\n */\n\nCHIP Computer {\n\n    IN reset;\n\n    PARTS:\n    // =========================================================================\n    // 1. INSTRUCTION ROM (ROM32K)\n    // =========================================================================\n    // Stores the program code. Addressed by the CPU's program counter (pc).\n    ROM32K(address=pcOut, out=instructionCode);\n\n    // =========================================================================\n    // 2. CENTRAL PROCESSING UNIT (CPU)\n    // =========================================================================\n    // Executes fetched instructions, accesses memory, computes results,\n    // and updates the program counter.\n    CPU(inM=memoryOut,\n        instruction=instructionCode,\n        reset=reset,\n        outM=cpuOutM,\n        writeM=cpuWriteM,\n        addressM=cpuAddressM,\n        pc=pcOut);\n\n    // =========================================================================\n    // 3. MAIN MEMORY & MEMORY-MAPPED I/O\n    // =========================================================================\n    // Combines Data RAM (16K), Screen memory (8K), and Keyboard register.\n    Memory(in=cpuOutM,\n           load=cpuWriteM,\n           address=cpuAddressM,\n           out=memoryOut);\n}\n";

export const boxAsm: string = "// =============================================================================\n// Nand to Tetris - Capstone Project\n// MAKE THE COMPUTER DRAW A BOX\n// Course: ETCCNT301 - Nand to Tetris - I\n// University: K.R. Mangalam University\n// Student Roll Number: 2501730041\n//\n// PARAMETERS CALCULATED FROM ROLL NUMBER:\n// - University Roll Number: 2501730041\n// - K (last two digits): 41\n// - K mod 3: 41 mod 3 = 2 (Duplicate Label Detection in Assembler)\n// - K mod 4: 41 mod 4 = 1\n//\n// BOX SPECIFICATIONS:\n// - Starting row: K = 41\n// - Height: 20 rows (rows 41 to 60)\n// - Width in pixels: 16 * ((K mod 4) + 1) = 16 * (1 + 1) = 32 pixels\n// - Words per row: (K mod 4) + 1 = 2 words (16 bits each = 32 bits total)\n// - Horizontal alignment: Left edge of screen (word offset 0 and 1)\n// - Starting screen address: SCREEN + (32 * K) = 16384 + (32 * 41) = 17696\n// - Ending screen row: 41 + 19 = 60\n// - Ending screen address: SCREEN + (32 * 60) + 1 = 16384 + 1920 + 1 = 18305\n//\n// BEHAVIOUR:\n// - Continuously monitors keyboard input at address KBD (24576).\n// - While any key is pressed (RAM[KBD] != 0), the box is drawn black (-1).\n// - When the key is released (RAM[KBD] == 0), the box is erased to white (0).\n// =============================================================================\n\n(MAIN_LOOP)\n    // -------------------------------------------------------------------------\n    // Step 1: Check keyboard input\n    // -------------------------------------------------------------------------\n    @KBD\n    D=M                 // D = current key code from keyboard register (RAM[24576])\n    @KEY_PRESSED\n    D;JNE               // If D != 0 (key is pressed), jump to KEY_PRESSED\n\n(KEY_RELEASED)\n    // Key is released -> set color to white (0)\n    @color\n    M=0                 // color = 0 (white / erase)\n    @DRAW_BOX\n    0;JMP\n\n(KEY_PRESSED)\n    // Key is pressed -> set color to black (-1 = 0xFFFF)\n    @color\n    M=-1                // color = -1 (black / draw all 16 pixels per word)\n\n(DRAW_BOX)\n    // -------------------------------------------------------------------------\n    // Step 2: Initialize box parameters\n    // Starting row address = SCREEN + (32 * 41) = 17696\n    // Row count = 20\n    // -------------------------------------------------------------------------\n    @17696\n    D=A\n    @row_addr\n    M=D                 // row_addr = 17696 (starting address of box at row 41)\n\n    @20\n    D=A\n    @rows_left\n    M=D                 // rows_left = 20 (height of box)\n\n(ROW_LOOP)\n    // -------------------------------------------------------------------------\n    // Step 3: Check if all 20 rows are completed\n    // -------------------------------------------------------------------------\n    @rows_left\n    D=M\n    @MAIN_LOOP\n    D;JLE               // If rows_left <= 0, return to main keyboard check loop\n\n    // -------------------------------------------------------------------------\n    // Step 4: Draw current row (Words per row = 2, total 32 pixels wide)\n    // Word 0: columns 0 to 15 (at row_addr)\n    // Word 1: columns 16 to 31 (at row_addr + 1)\n    // -------------------------------------------------------------------------\n    @color\n    D=M                 // D = fill color (-1 for black, 0 for white)\n\n    // Write Word 0\n    @row_addr\n    A=M\n    M=D                 // RAM[row_addr] = color (pixels 0..15)\n\n    // Write Word 1\n    @row_addr\n    A=M+1\n    M=D                 // RAM[row_addr + 1] = color (pixels 16..31)\n\n    // -------------------------------------------------------------------------\n    // Step 5: Advance to the next row\n    // Each screen row consists of 32 words (512 pixels / 16 = 32 words)\n    // row_addr = row_addr + 32\n    // rows_left = rows_left - 1\n    // -------------------------------------------------------------------------\n    @32\n    D=A\n    @row_addr\n    M=D+M               // row_addr = row_addr + 32 (Hack ALU uses D+M)\n\n    @rows_left\n    M=M-1               // rows_left = rows_left - 1\n\n    @ROW_LOOP\n    0;JMP               // Continue loop for next row\n";

