export const aluHdl: string = `// Nand to Tetris - Project 2
// File name: ALU.hdl

/**
 * The ALU (Arithmetic Logic Unit).
 * Computes one of the following functions:
 * x+y, x-y, y-x, 0, 1, -1, x, y, -x, -y, !x, !y,
 * x+1, y+1, x-1, y-1, x&y, x|y on two 16-bit inputs,
 * according to 6 input bits denoted zx,nx,zy,ny,f,no.
 */

CHIP ALU {
    IN  
        x[16], y[16],  // 16-bit inputs        
        zx, // zero the x input?
        nx, // negate the x input?
        zy, // zero the y input?
        ny, // negate the y input?
        f,  // compute (out = x + y) or (out = x & y)?
        no; // negate the out output?

    OUT 
        out[16], // 16-bit output
        zr,      // 1 if (out == 0), 0 otherwise
        ng;      // 1 if (out < 0),  0 otherwise

    PARTS:
    // Manipulate input x
    Mux16(a=x, b=false, sel=zx, out=zxOut);
    Not16(in=zxOut, out=notX);
    Mux16(a=zxOut, b=notX, sel=nx, out=xInput);

    // Manipulate input y
    Mux16(a=y, b=false, sel=zy, out=zyOut);
    Not16(in=zyOut, out=notY);
    Mux16(a=zyOut, b=notY, sel=ny, out=yInput);

    // Compute f: Add16 vs And16
    Add16(a=xInput, b=yInput, out=addOut);
    And16(a=xInput, b=yInput, out=andOut);
    Mux16(a=andOut, b=addOut, sel=f, out=fOut);

    // Post-negate out
    Not16(in=fOut, out=notFOut);
    Mux16(a=fOut, b=notFOut, sel=no, out=out, out[0..7]=lowOut, out[8..15]=highOut, out[15]=ng);

    // Evaluate zr
    Or8Way(in=lowOut, out=lowOr);
    Or8Way(in=highOut, out=highOr);
    Or(a=lowOr, b=highOr, out=anyNonZero);
    Not(in=anyNonZero, out=zr);
}
`;

